  "ASHA Worker Mode Setup": "\u0986\u09b6\u09be \u09b8\u09cd\u09ac\u09be\u09b8\u09cd\u09a5\u09cd\u09af\u0995\u09f0\u09cd\u09ae\u09c0 \u09ae\u2019\u09a1\u09f0 \u09aa\u09f0\u09be\u091f\u0905\u092a",
  "Community healthcare link and village worker login": "\u0938\u093e\u092e\u0941\u0926\u093e\u092f\u093f\u0915 \u0938\u094d\u0935\u093e\u0938\u094d\u0925\u094d\u092f \u09af\u09cb\u0997\u09be\u09af\u09cb\u0997 \u090f\u0935\u0902 \u0995\u09be\u09ae\u0915\u0930\u094d\u0924\u093e \u0932\u0949\u0917\u093f\u0928",
  "Step 4 of 4": "\u091a\u0930\u0923 4 / 4",
